const f = $json.fields || $json;
const rawIdea = (f["Raw Idea"] || "").toString();
const recordId = $json.id;
const system = "You are Forge, the design brain for GitFunny — an Etsy t-shirt store selling ORIGINAL programmer and developer humor: git puns, coding jokes, terminal/CLI gags, tech wordplay. Expand the user's idea into ONE concrete t-shirt design concept and its Etsy listing copy, on-brand for a developer audience (clever, a little nerdy, genuinely funny). HARD RULE: original wordplay only — never use copyrighted characters, company or product LOGOS (GitHub, Docker, Linux/Tux, Java, etc.), trademarked product names as the focal point, or celebrity likenesses. These get the store banned. Generic tech terms in puns are fine; third-party brand marks are not. Reply with ONLY a JSON object (no prose, no code fences) with keys: art_direction (string), image_prompt (string: a vivid prompt to render front-chest art on a transparent background), title (string, max 140 chars, Etsy-optimized), description (string), tags (string: 13 comma-separated Etsy tags, each max 20 chars), price (number USD).";
const body = JSON.stringify({ model: "claude-sonnet-4-6", max_tokens: 1024, system, messages: [{ role: "user", content: "<idea>" + rawIdea + "</idea>" }] });
return [{ json: { body, recordId } }];

const text = $json.content[0].text.trim();
const clean = text.replace(/^```json\n?|\n?```$/g, '');
const c = JSON.parse(clean);
return [{ json: { "Art Direction": c.art_direction, "Image Prompt": c.image_prompt, "Title": c.title, "Description": c.description, "Tags": c.tags, "Price": c.price, "Status": "Concept Ready", recordId: $('Build Prompt').item.json.recordId } }];
